dashboard.definition:
{
	"title": "Executive dashboard",
	"description": "At-a-glance operational posture — click any domain to drill down",
	"inputs": {
		"input_global_trp": {
			"options": {
				"defaultValue": "-4h@m,now",
				"token": "global_time"
			},
			"title": "",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			},
			"ds.spl2": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		},
		"tokens": {
			"default": {}
		}
	},
	"visualizations": {
		"viz_3ewlau3p": {
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/logo.png"
			},
			"type": "splunk.image"
		},
		"viz_C0hqav52": {
			"options": {
				"strokeColor": "#53a051"
			},
			"type": "abslayout.line"
		},
		"viz_SQjolf8o": {
			"options": {
				"strokeColor": "#53a051"
			},
			"type": "abslayout.line"
		},
		"viz_about_bg": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_clock": {
			"dataSources": {
				"primary": "ds_clock"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#6E6E6E",
				"majorFontSize": 12,
				"showDeltaValue": false,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "",
			"type": "splunk.singlevalue"
		},
		"viz_florida_bg": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "#E8E8E8"
			},
			"type": "splunk.rectangle"
		},
		"viz_florida_dot_aub": {
			"context": {
				"fillColorEditorConfig": [
					{
						"to": 50,
						"value": "#d9534f"
					},
					{
						"from": 50,
						"to": 70,
						"value": "#f0ad4e"
					},
					{
						"from": 70,
						"to": 85,
						"value": "#FFD442"
					},
					{
						"from": 85,
						"to": 95,
						"value": "#5cb85c"
					},
					{
						"from": 95,
						"value": "#088f44"
					}
				],
				"fillDataValue": "> primary | seriesByType(\"number\") | lastPoint()"
			},
			"dataSources": {
				"primary": "ds_florida_site_health_aub"
			},
			"options": {
				"fillColor": "> fillDataValue | rangeValue(fillColorEditorConfig)",
				"strokeColor": "#ffffff",
				"strokeWidth": 3
			},
			"type": "splunk.ellipse"
