			"name": "Active Devices Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\" | bin _time | stats latest(devicePresence.activeDevicesCount) as active by _time, devicePresence.location.name | stats sum(active) as total by _time",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_building_occupancy": {
			"name": "Occupancy",
			"options": {
				"extend": "ds_occupancy_trend",
				"query": "| fields _time rate"
			},
			"type": "ds.chain"
		},
		"ds_client_health_current": {
			"name": "Client Health",
			"options": {
				"extend": "ds_client_health_trend",
				"query": "| fields _time score"
			},
			"type": "ds.chain"
		},
		"ds_client_health_trend": {
			"name": "Client Health Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" scoreType=\"ALL\" clientType=\"ALL\" | timechart fixedrange=false latest(scoreValue) as score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_clients_total": {
			"name": "Active Clients",
			"options": {
				"extend": "ds_clients_trend",
				"query": "| fields _time total"
			},
			"type": "ds.chain"
		},
		"ds_clients_trend": {
			"name": "Active Clients Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" | timechart fixedrange=false dc(macAddress) as total",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_clock": {
			"name": "Clock",
			"options": {
				"query": "| makeresults \n| eval display=strftime(now(), \"%A, %B %d %Y — %I:%M %p\") \n| fields display",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"refresh": "30s",
				"refreshType": "delay"
			},
			"type": "ds.search"
		},
		"ds_dev_health_trend_exec": {
			"name": "Shared - ds_dev_health_trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" | eval h=case(Reachability==\"Reachable\" AND match(Manageability,\"^Managed\"),100, Reachability==\"Reachable\",50, 1==1,0) | timechart fixedrange=false avg(h) as score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_device_health_current": {
			"name": "Device Health",
			"options": {
				"extend": "ds_dev_health_trend_exec",
				"query": "| fields _time score"
			},
			"type": "ds.chain"
		},
		"ds_failed_logons_count": {
			"name": "Failed Auth",
			"options": {
				"extend": "ds_failed_logons_trend",
				"query": "| fields _time count"
			},
			"type": "ds.chain"
		},
		"ds_failed_logons_trend": {
			"name": "Failed Auth Trend",
			"options": {
				"query": "| tstats `summariesonly` dc(Authentication.user) as count from datamodel=Authentication where Authentication.action=\"failure\" by _time",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_florida_site_health_aub": {
			"name": "Auburndale site health",
			"options": {
				"extend": "ds_florida_site_health_base",
				"query": "| where like(Site, \"%AUB%\") OR like(Site, \"%Auburndale%\") | stats avg(health) as health | eval health=if(isnull(health),0,round(health))"
			},
			"type": "ds.chain"
		},
		"ds_florida_site_health_base": {
			"name": "Base Florida site health",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" | where Site!=\"\" | stats latest(OverallHealth) as h by DeviceID, Site | stats avg(h) as h by Site | eval health=round(h*10)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_florida_site_health_orl": {
			"name": "Orlando site health",
			"options": {
				"extend": "ds_florida_site_health_base",
				"query": "| where like(Site, \"%ORL%\") OR like(Site, \"%Orlando%\") | stats avg(health) as health | eval health=if(isnull(health),0,round(health))"
			},
			"type": "ds.chain"
		},
		"ds_florida_site_health_tlh": {
			"name": "Tallahassee site health",
			"options": {
				"extend": "ds_florida_site_health_base",
				"query": "| where like(Site, \"%TLH%\") OR like(Site, \"%Tallahassee%\") | stats avg(health) as health | eval health=if(isnull(health),0,round(health))"
			},
			"type": "ds.chain"
		},
		"ds_fw_blocked": {
			"name": "FW Blocked",
			"options": {
				"extend": "ds_fw_blocked_trend",
				"query": "| fields _time blocked"
			},
			"type": "ds.chain"
		},
		"ds_fw_blocked_trend": {
			"name": "FW Blocked Trend",
			"options": {
				"query": "| tstats `summariesonly` count from datamodel=Network_Traffic where All_Traffic.action=\"blocked\" by _time | rename count as blocked",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_issues_current": {
			"name": "Open Issues",
			"options": {
				"extend": "ds_issues_trend_exec",
				"query": "| fields _time issues"
			},
			"type": "ds.chain"
		},
		"ds_issues_trend_exec": {
			"name": "Open Issues Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\" | timechart fixedrange=false dc(IssueID) as issues",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_network_health_current": {
			"name": "Network Health",
			"options": {
				"extend": "ds_network_health_trend",
				"query": "| fields _time score"
			},
			"type": "ds.chain"
		},
		"ds_network_health_trend": {
			"name": "Network Health Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:networkhealth\" category=\"All\" | timechart fixedrange=false latest(healthScore) as score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_occupancy_trend": {
			"name": "Occupancy Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\" | bin _time | stats latest(spaceOccupancy.peoplePresence) as occupied by _time, spaceOccupancy.space.name | eval occupied=if(occupied==\"true\", 1, 0) | stats count as total_rooms, sum(occupied) as rooms_occupied by _time | eval rate=if(total_rooms>0, round(rooms_occupied/total_rooms*100, 2), 0)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_te_health": {
			"name": "ThousandEyes",
			"options": {
				"extend": "ds_te_health_trend",
				"query": "| fields _time score"
			},
			"type": "ds.chain"
		},
		"ds_te_health_trend": {
			"name": "ThousandEyes Trend",
			"options": {
				"query": "| tstats `summariesonly` avg(Test_Metrics.metric_name:network.loss) as loss, avg(Test_Metrics.metric_name:network.latency) as latency FROM datamodel=\"Cisco_ThousandEyes.Test_Metrics\" by _time | eval score=round(100 - coalesce(latency,0)/2 - coalesce(loss,0)*10, 2) | fields _time score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_threat_sources": {
			"name": "Threat Sources",
			"options": {
				"extend": "ds_threat_sources_trend",
				"query": "| fields _time sources"
			},
			"type": "ds.chain"
		},
		"ds_threat_sources_trend": {
			"name": "Threat Sources Trend",
			"options": {
				"query": "| tstats `summariesonly` dc(All_Traffic.src) as sources from datamodel=Network_Traffic where All_Traffic.action=\"blocked\" by _time",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wifi_clients": {
			"name": "Wi-Fi Clients",
			"options": {
				"extend": "ds_wifi_clients_trend",
				"query": "| fields _time clients"
			},
			"type": "ds.chain"
		},
		"ds_wifi_clients_trend": {
			"name": "Wi-Fi Clients Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\" deviceAssociation.event=\"ASSOCIATE\" | timechart fixedrange=false dc(deviceAssociation.device.macAddress) as clients",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		}
	},
